/// Extension methods for a boxed `Any` trait object
pub trait AnyBoxExt {
    /// Move the boxed value out of the box if it is of type `T`, or
    /// return the box if it isn't.
    fn move<T: 'static>(self) -> Result<Box<T>, Box<Any>>;
}

impl AnyBoxExt for Box<Any> {
    #[inline]
    fn move<T: 'static>(self) -> Result<Box<T>, Box<Any>> {
        if self.is::<T>() {
            unsafe {
                // Get the raw representation of the boxed trait object
                let to: TraitObject = transmute_copy(&self);

                // Reconstruct the box without dropping it
                let raw_box = Box::into_raw(self);
                Box::from_raw(raw_box as *mut T);

                // Return the correctly typed box
                Ok(transmute(to.data))
            }
        }

