/// A scheduling decision.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Decision {
    /// Accept the job.
    Accept,
    /// Reject the job.
    Reject,
    /// Postpone the decision.
    Postpone,
}

impl Schedule for Impartial {
    type Data = ();

    fn next(&mut self, _job: &Job) -> Result<Decision> {
        Ok(Decision::Accept)
    }

    fn push(&mut self, _time: f64, _data: Self::Data) -> Result<()> {
        Ok(())
    }
}

impl Schedule for Queue {
    type Data = Vec<Interval>;

    fn next(&mut self, job: &Job) -> Result<Decision> {
        if self.can_accommodate(job) {
            Ok(Decision::Accept)
        } else {
            Ok(Decision::Reject)
        }
    }

    fn push(&mut self, time: f64, data: Self::Data) -> Result<()> {
        self.advance(time, data)
    }
}

