impl<'dbtx, 't, T> Iterator for DatomsIterator<'dbtx, 't, T>
where T: Sized + Iterator<Item=Result<TxPart>> + 't {
    type Item = TxPart;

    fn next(&mut self) -> Option<TxPart> {
        if self.at_first {
            self.at_first = false;
            return Some(self.first.clone());
        }

        if self.at_last {
            return None;
        }

        match self.rows.next() {
            Some(Ok(part)) => {
                // Check if next row is a different transaction.
                match self.rows.peek() {
                    Some(Ok(next_part)) => {
                        if next_part.tx_id != part.tx_id {
                            self.at_last = true;
                        }
                    },
                    Some(Err(_)) => {
                        // Error case, stop iterating.
                        self.at_last = true;
                    },
                    None => {
                        // No more rows.
                        self.at_last = true;
                    }
                }
                Some(part)
            },
            Some(Err(_)) => {
                // Propagate error by stopping iteration.
                self.at_last = true;
                None
