    /// decrypts and verifies the ciphertext argument. Plaintext is returned as a vector of bytes
    pub fn decrypt_and_verify(&self, ciphertext: &[u8]) -> Option<Vec<u8>> {
        let mut cleartext = chacha20::stream_xor(ciphertext, &self.nonce, &self.encryption_key);

        if cleartext.len() < hmacsha512256::TAGBYTES {
            return None;
        }

        let tag_start = cleartext.len() - hmacsha512256::TAGBYTES;
