    /// decrypts and verifies the ciphertext argument. The plaintext is returned as a vector of bytes.
    /// If the authentication tag is invalid, returns None.
    pub fn decrypt_and_verify(&self, ciphertext: &[u8]) -> Option<Vec<u8>> {
        let mut cleartext = chacha20::stream_xor(ciphertext, &self.nonce, &self.encryption_key);

        if cleartext.len() < hmacsha512256::TAGBYTES {
            return None;
        }

        let split_point = cleartext.len() - hmacsha512256::TAGBYTES;
        let (message, auth_tag_slice) = cleartext.split_at_mut(split_point);

        let auth_tag = hmacsha512256::Tag::from_slice(auth_tag_slice).unwrap();

        if hmacsha512256::verify(&auth_tag, message, &self.authentication_key) {
            cleartext.truncate(split_point);
            Some(cleartext)
        } else {
            None
        }
    }
}

