    /// decrypts the ciphertext argument. Returns None if the authorization fails, and Some(plaintext_vec) otherwise
    pub fn decrypt_and_verify(&self, ciphertext: &[u8]) -> Option<Vec<u8>> {
        let mut cleartext = chacha20::stream_xor(ciphertext, &self.nonce, &self.encryption_key);
        if cleartext.len() < AUTH_TAG_BYTES {
            return None;
        }
        let message_len = cleartext.len() - AUTH_TAG_BYTES;
        let (message, tag_slice) = cleartext.split_at_mut(message_len);
        let check = hmacsha512256::verify(
            &hmacsha512256::Tag::from_slice(tag_slice).unwrap(),
            message,
            &self.authentication_key,
        );
        if check {
            cleartext.truncate(message_len);
            Some(cleartext)
        } else {
            None
        }
    }

