    async fn measure_latency(&mut self) -> io::Result<()> {
        let mut min_latency = Duration::from_secs(60);
        for &addr in &self.addresses {
            let start = Instant::now();
            match unblock(move || TcpStream::connect((addr, self.port))).await {
                Ok(_) => {
                    let latency = start.elapsed();
                    if latency < min_latency {
                        min_latency = latency;
                    }
                }
                Err(_) => continue,
            }
        }
        self.latency = min_latency;
        Ok(())
    }
}

