        tonemap_unit.tonemap(&gather_unit.tristimulus_buffer);

        // Copy the rendered image.
        let img = tonemap_unit.rgb_buffer.clone();

        // And send it to the UI / main task.
        img_tx.send(img).unwrap();
    }

