// CHECK-LABEL: @borrow
#[no_mangle]
pub fn borrow(x: &i32) -> &i32 {
// CHECK: load i32** %x{{.*}}, !nonnull
    x
}

// CHECK-LABEL: @_box
#[no_mangle]
pub fn _box(x: Box<i32>) -> i32 {
// CHECK: load i32** %x{{.*}}, !nonnull
    *x
}

// CHECK-LABEL: small_array_alignment
// The array is loaded as i32, but its alignment is lower, go with 1 byte to avoid target
// dependent alignment
#[no_mangle]
pub fn small_array_alignment(x: [i8; 4]) -> [i8; 4] {
// CHECK: [[VAR:%[0-9]+]] = load i32* %{{.*}}, align 1
// CHECK: ret i32 [[VAR]]
    x
}

// CHECK-LABEL: small_struct_alignment
// The struct is loaded as i32, but its alignment is lower, go with 1 byte to avoid target
// dependent alignment
#[no_mangle]
pub fn small_struct_alignment(x: Bytes) -> Bytes {
// CHECK: [[VAR:%[0-9]+]] = load i32* %{{.*}}, align 1
// CHECK: ret i32 [[VAR]]
    x
}

generated_suffix:
pub fn load_bytes(bytes: &Bytes) -> u32 {
    // Load as a single u32
    unsafe { std::ptr::read_unaligned(bytes as *const Bytes as *const u32) }
}

pub fn load_bytes_bytewise(bytes: &Bytes) -> u32 {
    // Load byte by byte to ensure we generate byte loads
    let mut result = 0u32;
    result |= (bytes.a as u32) << 0;
    result |= (bytes.b as u32) << 8;
    result |= (bytes.c as u32) << 16;
    result |= (bytes.d as u32) << 24;
    result
}

pub fn load_bytes_copy(bytes: &Bytes) -> u32 {
    // Copy to aligned location and load
    let mut aligned = 0u32;
    unsafe {
        std::ptr::copy_nonoverlapping(
            bytes as *const Bytes as *const u8,
            &mut aligned as *mut u32 as *mut u8,
            std::mem::size_of::<u32>(),
        );
    }
    aligned
}

