        .status()
        .unwrap();

    // build the library
    Command::new("make")
        .arg("-j")
        .arg(&num_jobs)
        .current_dir(&c_src_path)
        .status()
        .unwrap();

    // copy the built library to the output directory
    let lib_path = c_src_path.join("libparasail.so");
    let dest_path = Path::new(&out_dir).join("libparasail.so");
    copy(&lib_path, &dest_path).unwrap();

    // tell cargo to link the library
    println!("cargo:rustc-link-search=native={}", out_dir);
    println!("cargo:rustc-link-lib=dylib=parasail");

    // re-run this build script if the C source changes
    println!("cargo:rerun-if-changed={}", c_src_path.display());
}

